document.getElementById("parent-div").addEventListener("click", () => console.log("PARENT"));
document.getElementById("child-div").addEventListener("click", () => console.log("CHILD"));

// Klikniecie w #inner-btn (zagniezdzony w child-div, ktory jest w parent-div)
// wypisze w kolejnosci:
// "CHILD"  (najblizszy przodek z handlerem)
// "PARENT" (nastepny przodek w gore drzewa DOM)

document.getElementById("todo-list").addEventListener("click", (e) => {
  if (e.target.dataset.action === "delete") {
    e.target.closest("li").remove();
  }
});

document.getElementById("todo-list").addEventListener("click", (e) => {
  if (e.target.dataset.action === "delete") {
    e.target.closest("li").remove();
  }
  if (e.target.type === "checkbox") {
    e.target.closest("li").style.textDecoration = e.target.checked ? "line-through" : "none";
  }
});

document.getElementById("todo-add").addEventListener("click", () => {
  const input = document.getElementById("todo-input");
  const text = input.value.trim();
  if (!text) return;

  const li = document.createElement("li");
  li.innerHTML = `<input type="checkbox"> ${text} <button data-action="delete">X</button>`;
  document.getElementById("todo-list").appendChild(li);
  input.value = "";
});

// Listener z zadania 3 jest podpiety do RODZICA (#todo-list), nie do
// konkretnych <li>. Kazde klikniecie na dowolny element WEWNATRZ
// #todo-list (rowniez ten dodany PO podpieciu listenera) automatycznie
// 'bubbinguje' w gore drzewa DOM az do #todo-list, gdzie handler
// sprawdza e.target - dziala wiec IDENTYCZNIE dla starych i nowych
// elementow, bo listener 'lapie' zdarzenie na poziomie rodzica,
// niezaleznie od tego, kiedy dokladnie dany <li> zostal dodany do drzewa.

// Delegacja zdarzen jest bardziej wydajna, poniewaz JEDEN nasluchiwacz
// (podpiety na rodzicu) zuzywa znacznie mniej pamieci i zasobow
// przegladarki niz SETKI osobnych nasluchiwaczy, po jednym na kazdy
// element listy. Przy duzej liczbie elementow (np. tysiacach wpisow
// listy zadan) roznica staje sie znaczaca, zarowno pod wzgledem
// zuzycia pamieci, jak i czasu potrzebnego na podpiecie wszystkich
// nasluchiwaczy.

function symulujBubbling(sciezka, handlery) {
  const wyniki = [];
  for (const el of sciezka) {
    if (handlery[el]) wyniki.push(handlery[el]());
  }
  return wyniki;
}

console.log(symulujBubbling(["child", "parent", "body"], {
  child: () => "CHILD",
  parent: () => "PARENT"
}));

function symulujClosest(sciezka, warunek) {
  return sciezka.find(warunek) ?? null;
}

console.log(symulujClosest(["span", "li", "ul", "body"], (el) => el === "li"));
console.log(symulujClosest(["span", "li", "ul", "body"], (el) => el === "table"));

const symulujacyListeDelegacji = {
  akcje: {},
  dodajAkcje(nazwa, fn) {
    this.akcje[nazwa] = fn;
  },
  obsluz(nazwaAkcji) {
    return this.akcje[nazwaAkcji] ? this.akcje[nazwaAkcji]() : "brak akcji";
  }
};

symulujacyListeDelegacji.dodajAkcje("usun", () => "usunieto");
console.log(symulujacyListeDelegacji.obsluz("usun"));
console.log(symulujacyListeDelegacji.obsluz("edytuj"));

function dodajZadanie(lista, tekst) {
  lista.push({ tekst, zaznaczone: false });
  return lista.length;
}

const zadania = [];
console.log(dodajZadanie(zadania, "Kupic mleko"));
console.log(dodajZadanie(zadania, "Umyc auto"));
console.log(zadania);

function usunZadanie(lista, indeks) {
  lista.splice(indeks, 1);
  return lista;
}

console.log(usunZadanie(["a", "b", "c"], 1));

function przelaczZaznaczenie(zadanie) {
  zadanie.zaznaczone = !zadanie.zaznaczone;
  return zadanie;
}

const z = { tekst: "Test", zaznaczone: false };
console.log(przelaczZaznaczenie(z));
console.log(przelaczZaznaczenie(z));

function policzZaznaczone(lista) {
  return lista.filter(z => z.zaznaczone).length;
}

console.log(policzZaznaczone([
  { tekst: "a", zaznaczone: true },
  { tekst: "b", zaznaczone: false },
  { tekst: "c", zaznaczone: true }
]));

function zbudujSciezke(elementKoncowy, mapaRodzicow) {
  const sciezka = [elementKoncowy];
  let aktualny = elementKoncowy;
  while (mapaRodzicow[aktualny]) {
    aktualny = mapaRodzicow[aktualny];
    sciezka.push(aktualny);
  }
  return sciezka;
}

console.log(zbudujSciezke("span", { span: "li", li: "ul", ul: "body" }));

function symulujStopPropagation(sciezka, zatrzymajNa) {
  const wynik = [];
  for (const el of sciezka) {
    wynik.push(el);
    if (el === zatrzymajNa) break;
  }
  return wynik;
}

console.log(symulujStopPropagation(["li", "ul", "body"], "ul"));

function renderujListe(zadania) {
  return zadania.map(z => (z.zaznaczone ? "[x] " : "[ ] ") + z.tekst);
}

console.log(renderujListe([
  { tekst: "Kupic mleko", zaznaczone: false },
  { tekst: "Umyc auto", zaznaczone: true }
]));

function znajdzZadaniePoTekscie(zadania, tekst) {
  return zadania.findIndex(z => z.tekst === tekst);
}

console.log(znajdzZadaniePoTekscie([{ tekst: "a" }, { tekst: "b" }], "b"));
console.log(znajdzZadaniePoTekscie([{ tekst: "a" }], "z"));

function obsluzKlikDelegowany(akcja, indeks, zadania) {
  if (akcja === "usun") {
    zadania.splice(indeks, 1);
  } else if (akcja === "przelacz") {
    zadania[indeks].zaznaczone = !zadania[indeks].zaznaczone;
  }
  return zadania;
}

const lista = [{ tekst: "a", zaznaczone: false }, { tekst: "b", zaznaczone: false }];
obsluzKlikDelegowany("przelacz", 0, lista);
console.log(lista);

function jestWTejSamejGalezi(sciezkaA, sciezkaB) {
  return sciezkaA.some(el => sciezkaB.includes(el));
}

console.log(jestWTejSamejGalezi(["a", "b", "body"], ["c", "b", "body"]));
console.log(jestWTejSamejGalezi(["a"], ["c"]));

function policzKlikniedaWSekcji(historia, sekcja) {
  return historia.filter(h => h.sekcja === sekcja).length;
}

console.log(policzKlikniedaWSekcji([
  { sekcja: "start" }, { sekcja: "kontakt" }, { sekcja: "start" }
], "start"));

function ostatniaAkcja(historiaAkcji) {
  const ostatnia = historiaAkcji[historiaAkcji.length - 1];
  return ostatnia.akcja + " na indeksie " + ostatnia.indeks;
}

console.log(ostatniaAkcja([{ akcja: "usun", indeks: 0 }, { akcja: "przelacz", indeks: 2 }]));

function zbudujMenuZLinkow(nazwy) {
  return nazwy.map(n => ({ nazwa: n, href: "#" + n.toLowerCase() }));
}

console.log(zbudujMenuZLinkow(["Start", "Kontakt", "Oferta"]));

function symulujMatches(element, selektorTyp) {
  return element.typ === selektorTyp;
}

console.log(symulujMatches({ typ: "button" }, "button"));
console.log(symulujMatches({ typ: "span" }, "button"));

function zbudujDrzewo(struktura) {
  let wynik = [struktura.nazwa];
  for (const dziecko of struktura.dzieci || []) {
    wynik = wynik.concat(zbudujDrzewo(dziecko));
  }
  return wynik;
}

console.log(zbudujDrzewo({ nazwa: "ul", dzieci: [{ nazwa: "li1", dzieci: [] }, { nazwa: "li2", dzieci: [] }] }));

function resetujFormularzDelegowany(pola) {
  for (const klucz in pola) {
    pola[klucz] = "";
  }
  return pola;
}

