function grupujAkcjePoTypie(historia) {
  const mapa = new Map();
  historia.forEach((h) => {
    if (!mapa.has(h.typ)) mapa.set(h.typ, []);
    mapa.get(h.typ).push(h);
  });
  return mapa;
}

const wynik = grupujAkcjePoTypie([{ typ: "usun", id: 1 }, { typ: "usun", id: 2 }, { typ: "edytuj", id: 3 }]);
console.log(wynik.get("usun").length, wynik.get("edytuj").length);

