function sortujZadaniaWedlugStanu(zadania) {
  const niezaznaczone = zadania.filter(z => !z.zaznaczone);
  const zaznaczone = zadania.filter(z => z.zaznaczone);
  return niezaznaczone.concat(zaznaczone);
}

